#!/usr/bin/env node
/**
 * Generate Play Store + App Store graphics from the brand assets.
 *
 * Outputs:
 *   - android/app/src/main/play/listings/en-US/graphics/icon/1.png   (512×512)
 *   - android/app/src/main/play/listings/en-US/graphics/feature-graphic/1.png  (1024×500)
 *
 * Sprint 7 (S7-H) — placeholder graphics for first store push. Designed to be
 * replaceable once design delivers final art; the feature graphic uses brand
 * color + app name + tagline composed via satori SVG render → PNG.
 *
 * Phone screenshots are NOT generated by this script — those need to come from
 * a running iOS simulator + Android emulator (capture the actual app screens).
 *
 * Usage: node scripts/generate-store-graphics.mjs
 */

import sharp from 'sharp';
import satori from 'satori';
import {readFile, writeFile, mkdir} from 'node:fs/promises';
import {join, dirname} from 'node:path';
import {fileURLToPath} from 'node:url';

const __dirname = dirname(fileURLToPath(import.meta.url));
const REPO = join(__dirname, '..');

const PLAY_GFX = join(
  REPO,
  'android/app/src/main/play/listings/en-US/graphics',
);

const BRAND_TEAL = '#8dc9d6';
const BRAND_TEAL_DEEP = '#5fa9b8';
const TEXT_DARK = '#0f2329';

async function loadFont(weight = 700) {
  const candidates = [
    `Manrope-${weight === 700 ? 'Bold' : weight === 600 ? 'SemiBold' : 'Regular'}.ttf`,
  ];
  for (const c of candidates) {
    try {
      const buf = await readFile(join(REPO, 'assets/fonts', c));
      return buf;
    } catch {}
  }
  throw new Error(`No font found for weight ${weight}`);
}

async function generateIcon() {
  const out = join(PLAY_GFX, 'icon/1.png');
  await mkdir(dirname(out), {recursive: true});
  // Play wants 512×512, no transparency. Resize and flatten on white in case.
  await sharp(join(REPO, 'assets/branding/icon.png'))
    .resize(512, 512, {fit: 'cover'})
    .flatten({background: '#ffffff'})
    .png({compressionLevel: 9})
    .toFile(out);
  console.log(`✓ ${out}`);
}

async function generateFeatureGraphic() {
  const W = 1024;
  const H = 500;
  const out = join(PLAY_GFX, 'feature-graphic/1.png');
  await mkdir(dirname(out), {recursive: true});

  const bold = await loadFont(700);
  const semibold = await loadFont(600);

  const svg = await satori(
    {
      type: 'div',
      props: {
        style: {
          width: W,
          height: H,
          display: 'flex',
          flexDirection: 'column',
          justifyContent: 'center',
          alignItems: 'flex-start',
          padding: '0 80px',
          background: `linear-gradient(135deg, ${BRAND_TEAL} 0%, ${BRAND_TEAL_DEEP} 100%)`,
          color: TEXT_DARK,
          fontFamily: 'Manrope',
        },
        children: [
          {
            type: 'div',
            props: {
              style: {
                fontSize: 96,
                fontWeight: 700,
                lineHeight: 1.0,
                marginBottom: 16,
              },
              children: 'Qariah',
            },
          },
          {
            type: 'div',
            props: {
              style: {
                fontSize: 36,
                fontWeight: 600,
                lineHeight: 1.2,
                opacity: 0.85,
                maxWidth: 720,
              },
              children: "The Qur'an, in her voice.",
            },
          },
          {
            type: 'div',
            props: {
              style: {
                fontSize: 24,
                fontWeight: 600,
                lineHeight: 1.2,
                marginTop: 28,
                opacity: 0.7,
              },
              children:
                '63 women reciters · 9 riwāyāt · 1,301 recitations · ad-free',
            },
          },
        ],
      },
    },
    {
      width: W,
      height: H,
      fonts: [
        {name: 'Manrope', data: bold, weight: 700, style: 'normal'},
        {name: 'Manrope', data: semibold, weight: 600, style: 'normal'},
      ],
    },
  );

  // satori returns SVG; convert to PNG via sharp
  await sharp(Buffer.from(svg)).png({compressionLevel: 9}).toFile(out);
  console.log(`✓ ${out}`);
}

async function main() {
  await generateIcon();
  await generateFeatureGraphic();
  console.log('\nDone.');
  console.log(
    'Phone screenshots still needed (capture from running app on device/sim).',
  );
}

main().catch(e => {
  console.error(e);
  process.exit(1);
});
